/**
 * Exercise catalog (ADR-0101, expanded ADR-0112). Covers every `MovementPattern`
 * and `EquipmentType` in the v0 vocabulary. Kept as typed in-code data for now;
 * can move to a data file/DB later without changing the `Exercise` shape.
 *
 * Multiple exercises intentionally share a `movementPattern` so the engine can
 * substitute within a pattern when avoidance flags exclude one (ADR-0106).
 *
 * Isolation-lift pattern convention (ADR-0112): the schema has no dedicated
 * "isolation" pattern, so single-joint accessory lifts are filed under the
 * compound pattern they most resemble mechanically — biceps curls/shrugs/rear-
 * delt work under `pull`, triceps/lateral-raise work under `push`, calf raises
 * under `squat`. This keeps them in the right substitution pool (e.g. a calf
 * raise is a safe swap-in when a knee flag excludes a squat variant).
 */

